<script lang="ts">
  import { onMount } from 'svelte';
  import QRCode from 'qrcode';
  import { importRecoveryKit } from '@unkeep/core';
  import { approvePairingRequest, clearDeviceAccess, createPairingRequest, inspectPairingCode, waitForPairing, RelayClient, type DeviceCredential, type PairingSession, type PendingPairingRequest, type RelaySession, type ServiceCredential } from '@unkeep/client';
  import { deviceKeyStore, relaySessionStore } from '$lib/clientStorage';
  import { downloadRecoveryKit } from '$lib/recoveryKit';
  import { theme } from '$lib/theme.svelte';
  import { loadLocalVault } from '$lib/vaultBoot';
  const themeModes = ['system', 'light', 'dark'] as const;

  export interface VaultReady { ownerId:string;masterKey:Uint8Array<ArrayBuffer>;session:RelaySession;migrateLegacy:boolean }
  let {onReady,onSignedOut}:{onReady:(vault:VaultReady)=>void|Promise<void>;onSignedOut?:()=>void|Promise<void>}=$props();
  type View='loading'|'connect'|'setup'|'choose'|'pairing'|'recovery-confirm'|'legacy-recovery-warning'|'reclaim'|'ready';
  let view=$state<View>('loading'),endpoint=$state(''),relayInstanceId=$state(''),setupToken=$state(''),recoveryToken=$state(''),error=$state<string|null>(null),busy=$state(false),recoverySaved=$state(false),recoveryKit=$state(''),pairing=$state<PairingSession|null>(null),pairingQr=$state(''),pairingCode=$state(''),notice=$state<string|null>(null),menu=$state(false);
  let devices=$state<DeviceCredential[]>([]),serviceCredentials=$state<ServiceCredential[]>([]),serviceName=$state(''),mintedServiceCredential=$state(''),credentialsBusy=$state(false);
  let activeKey=$state<Uint8Array<ArrayBuffer>|null>(null),activeSession=$state<RelaySession|null>(null),abort:AbortController|null=null;
  let hasLocalKey=$state(false);
  let pendingApproval=$state<PendingPairingRequest|null>(null);
  let pendingLegacyRecoveryKit=$state('');

  onMount(()=>{void (async()=>{try{endpoint=await relaySessionStore.defaultEndpoint(window.location.origin)}catch{endpoint=window.location.origin}await boot()})();return()=>abort?.abort()});
  async function ready(session:RelaySession,key:Uint8Array<ArrayBuffer>,migrateLegacy=false){await onReady({ownerId:session.instanceId,masterKey:key,session,migrateLegacy});activeSession=session;activeKey=key;hasLocalKey=true;notice=null;view='ready'}
  async function boot(){try{const local=await loadLocalVault(relaySessionStore,deviceKeyStore);if(local){endpoint=local.session.endpoint;relayInstanceId=local.session.instanceId;await ready(local.session,local.masterKey,true);if(!navigator.onLine)notice='Offline — showing the local working copy';return}hasLocalKey=await deviceKeyStore.hasDeviceKeys();view='connect'}catch(e){error=e instanceof Error?e.message:String(e);view='connect'}}
  async function connect(){busy=true;error=null;try{await relaySessionStore.saveEndpoint(endpoint);const status=await new RelayClient(endpoint).status();relayInstanceId=status.instanceId;view=status.initialized?'choose':'setup'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function claim(){if(!relayInstanceId)return;busy=true;error=null;try{const existing=await deviceKeyStore.unlockDevice(relayInstanceId);if(existing){activeKey=existing;recoveryKit=await deviceKeyStore.createRecoveryKit()}else{const provisioned=await deviceKeyStore.provisionFirstDevice(relayInstanceId);activeKey=provisioned.masterKey;recoveryKit=provisioned.recoveryKit}recoverySaved=false;view='recovery-confirm'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function finishSetup(){if(!recoverySaved||!activeKey||!relayInstanceId)return;busy=true;error=null;try{const deviceId=await deviceKeyStore.getDeviceId();const result=await new RelayClient(endpoint).claimSetup(setupToken,deviceId,navigator.userAgent.slice(0,100));if(result.instanceId!==relayInstanceId)throw new Error('Relay instance changed during setup');const session={endpoint,instanceId:result.instanceId,deviceId,credential:result.deviceCredential};await relaySessionStore.save(session);setupToken='';await ready(session,activeKey)}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function startPairing(){busy=true;error=null;try{pairing=await createPairingRequest(endpoint,deviceKeyStore,navigator.userAgent.slice(0,100));pairingQr=await QRCode.toDataURL(JSON.stringify({type:'unkeep-pair',endpoint,code:pairing.code}));view='pairing';abort=new AbortController();const result=await waitForPairing(pairing,{keyStore:deviceKeyStore,sessionStore:relaySessionStore,signal:abort.signal});await ready(result.session,result.masterKey)}catch(e){if((e as Error).name!=='AbortError')error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  function cancelPairing(){abort?.abort();abort=null;pairing=null;pairingQr='';error=null;busy=false;view='choose'}
  async function restore(file:File){if(!relayInstanceId)return;busy=true;error=null;try{const serialized=await file.text();const kit=importRecoveryKit(serialized);if(kit.version===1){await deviceKeyStore.validateLegacyRecovery(serialized,relayInstanceId);pendingLegacyRecoveryKit=serialized;view='legacy-recovery-warning';return}activeKey=await deviceKeyStore.restoreDeviceFromRecovery(serialized,relayInstanceId);recoveryToken='';notice='Encryption key restored locally. Enter the operator recovery token to restore server access.';view='reclaim'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function confirmLegacyRecovery(){if(!pendingLegacyRecoveryKit||!relayInstanceId)return;busy=true;error=null;try{activeKey=await deviceKeyStore.restoreLegacyDeviceFromRecovery(pendingLegacyRecoveryKit,relayInstanceId);pendingLegacyRecoveryKit='';recoveryToken='';notice='Legacy recovery kit associated with this relay. Enter the operator recovery token to restore server access.';view='reclaim'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  function cancelLegacyRecovery(){pendingLegacyRecoveryKit='';error=null;view='choose'}
  async function reclaim(){if(!activeKey||!relayInstanceId)return;busy=true;error=null;try{const deviceId=await deviceKeyStore.getDeviceId();const result=await new RelayClient(endpoint).reclaimSetup(recoveryToken,deviceId,navigator.userAgent.slice(0,100));if(result.instanceId!==relayInstanceId)throw new Error('Relay instance changed during recovery');const session={endpoint,instanceId:result.instanceId,deviceId,credential:result.deviceCredential};await relaySessionStore.save(session);recoveryToken='';await ready(session,activeKey)}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function reviewPairing(){if(!activeSession||!pairingCode.trim())return;busy=true;error=null;try{pendingApproval=await inspectPairingCode(activeSession,pairingCode)}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function approveReviewed(){if(!activeSession||!activeKey||!pendingApproval)return;busy=true;error=null;try{await approvePairingRequest(activeSession,pendingApproval,activeKey);notice=`${pendingApproval.deviceName} approved`;pairingCode='';pendingApproval=null;await loadCredentials()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  function cancelApproval(){pendingApproval=null;pairingCode=''}
  async function loadCredentials(){if(!activeSession)return;credentialsBusy=true;error=null;try{const relay=new RelayClient(activeSession.endpoint,activeSession.credential);const [deviceList,serviceList]=await Promise.all([relay.devices(),relay.serviceCredentials()]);devices=deviceList.devices;serviceCredentials=serviceList.serviceCredentials}catch(e){error=e instanceof Error?e.message:String(e)}finally{credentialsBusy=false}}
  async function toggleMenu(){menu=!menu;if(!menu)pendingApproval=null;if(menu)await loadCredentials()}
  async function mintService(){if(!activeSession||!serviceName.trim())return;credentialsBusy=true;error=null;notice=null;try{const result=await new RelayClient(activeSession.endpoint,activeSession.credential).mintServiceCredential(serviceName);mintedServiceCredential=result.serviceCredential;serviceName='';notice='Copy this credential now. It will not be shown again.';await loadCredentials()}catch(e){error=e instanceof Error?e.message:String(e)}finally{credentialsBusy=false}}
  async function revokeDevice(id:string,name:string){if(!activeSession||id===activeSession.deviceId||!window.confirm(`Revoke ${name}? That device will lose sync access.`))return;credentialsBusy=true;error=null;try{await new RelayClient(activeSession.endpoint,activeSession.credential).revokeDevice(id);await loadCredentials()}catch(e){error=e instanceof Error?e.message:String(e)}finally{credentialsBusy=false}}
  async function revokeService(id:string){if(!activeSession)return;credentialsBusy=true;error=null;try{await new RelayClient(activeSession.endpoint,activeSession.credential).revokeServiceCredential(id);await loadCredentials()}catch(e){error=e instanceof Error?e.message:String(e)}finally{credentialsBusy=false}}
  async function disconnect(){busy=true;error=null;try{await onSignedOut?.();await relaySessionStore.clear();activeKey=null;activeSession=null;hasLocalKey=true;menu=false;view='connect'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
  async function forgetLocalAccess(){if(!window.confirm('Forget this vault key and connection on this browser? Local vault data will stay isolated until you pair that vault again.'))return;busy=true;error=null;try{abort?.abort();await onSignedOut?.();await clearDeviceAccess(deviceKeyStore,relaySessionStore);activeKey=null;activeSession=null;hasLocalKey=false;menu=false;notice='Stored vault access cleared. You can now connect a different vault.';view='connect'}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
</script>

{#if view==='ready'}
  <div class="fixed right-2 top-[calc(0.875rem+env(safe-area-inset-top))] z-50 sm:right-3"><button class="rounded-full p-2 text-on-surface-muted hover:bg-surface-dim hover:text-on-surface" aria-label="Device menu" aria-expanded={menu} onclick={()=>void toggleMenu()}><svg class="h-5 w-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 6a2 2 0 110-4 2 2 0 010 4zm0 6a2 2 0 110-4 2 2 0 010 4zm0 6a2 2 0 110-4 2 2 0 010 4z"/></svg></button>{#if menu}<div class="absolute right-0 mt-2 max-h-[calc(100dvh-4rem)] w-80 max-w-[calc(100vw-1rem)] overflow-y-auto rounded-xl border border-border bg-surface p-4 shadow-xl"><p class="truncate text-sm">{activeSession?.endpoint}</p><div class="mt-3 flex items-center gap-1 text-sm"><span class="mr-auto text-on-surface-muted">Theme</span>{#each themeModes as mode}<button class="rounded-full px-2.5 py-1 capitalize {theme.mode === mode ? 'bg-primary/15 text-primary' : 'text-on-surface-muted hover:bg-surface-dim'}" onclick={() => theme.set(mode)}>{mode}</button>{/each}</div>{#if pendingApproval}<div class="mt-3 rounded-lg border border-border bg-surface-dim p-3 text-sm"><p>Approve access for <strong>{pendingApproval.deviceName}</strong>?</p><p class="mt-1 break-all text-xs text-on-surface-muted">Device ID: <code>{pendingApproval.deviceId}</code></p><div class="mt-3 flex gap-2"><button class="rounded bg-primary px-2 py-1 text-on-primary disabled:opacity-50" disabled={busy} onclick={()=>void approveReviewed()}>Approve device</button><button class="rounded border border-border px-2 py-1" disabled={busy} onclick={cancelApproval}>Cancel</button></div></div>{:else}<form class="mt-3 flex gap-2" onsubmit={e=>{e.preventDefault();void reviewPairing()}}><input class="min-w-0 flex-1 rounded border border-border bg-surface px-2" aria-label="Pairing code" placeholder="PAIR CODE" bind:value={pairingCode} required/><button class="rounded bg-primary px-2 py-1 text-on-primary disabled:opacity-50" disabled={busy}>Review device</button></form>{/if}<div class="mt-4 border-t border-border pt-3"><p class="text-xs font-semibold uppercase tracking-wide text-on-surface-muted">Devices</p>{#if credentialsBusy && !devices.length}<p class="mt-2 text-xs text-on-surface-muted">Loading…</p>{:else if !devices.length}<p class="mt-2 text-xs text-on-surface-muted">No devices</p>{:else}<ul class="mt-2 grid gap-1 text-sm">{#each devices as device}<li class="flex items-center gap-2"><span class="min-w-0 flex-1 truncate">{device.name}</span>{#if device.revokedAt}<span class="text-xs text-on-surface-muted">Revoked</span>{:else if device.id===activeSession?.deviceId}<span class="text-xs text-on-surface-muted">Current</span>{:else}<button class="text-xs text-danger disabled:opacity-50" disabled={credentialsBusy} onclick={()=>void revokeDevice(device.id,device.name)}>Revoke</button>{/if}</li>{/each}</ul>{/if}</div><div class="mt-4 border-t border-border pt-3"><p class="text-xs font-semibold uppercase tracking-wide text-on-surface-muted">Service credentials</p>{#if !serviceCredentials.length}<p class="mt-2 text-xs text-on-surface-muted">None</p>{:else}<ul class="mt-2 grid gap-1 text-sm">{#each serviceCredentials as service}<li class="flex items-center gap-2"><span class="min-w-0 flex-1 truncate">{service.name}</span>{#if service.revokedAt}<span class="text-xs text-on-surface-muted">Revoked</span>{:else}<button class="text-xs text-danger disabled:opacity-50" disabled={credentialsBusy} onclick={()=>void revokeService(service.id)}>Revoke</button>{/if}</li>{/each}</ul>{/if}<form class="mt-2 flex gap-2" onsubmit={e=>{e.preventDefault();void mintService()}}><input class="min-w-0 flex-1 rounded border border-border bg-surface px-2" aria-label="Credential name" placeholder="Credential name" bind:value={serviceName} required/><button class="rounded bg-primary px-2 py-1 text-on-primary disabled:opacity-50" disabled={credentialsBusy}>Mint</button></form>{#if mintedServiceCredential}<code class="mt-2 block break-all rounded bg-surface-dim p-2 text-xs select-all">{mintedServiceCredential}</code>{/if}</div>{#if notice}<p class="mt-2 text-xs text-primary">{notice}</p>{/if}{#if error}<p class="mt-2 text-xs text-danger">{error}</p>{/if}<div class="mt-3 flex flex-col items-start gap-2"><button class="text-sm text-on-surface-muted" onclick={disconnect}>Disconnect sync</button><button class="text-sm text-danger" onclick={()=>void forgetLocalAccess()}>Forget stored vault key and switch</button></div></div>{/if}</div>
{:else}
  <main class="grid min-h-dvh place-items-center bg-surface-dim p-4"><section class="w-full max-w-md rounded-2xl border border-border bg-surface p-6 shadow-lg">
    <div class="mb-5 flex items-center gap-3"><img src="/icon.svg" alt="" class="h-12 w-12"/><div><h1 class="text-2xl font-semibold">UnKeep</h1><p class="text-sm text-on-surface-muted">Your notes. Your storage.</p></div></div>
    {#if view==='loading'}<p>Opening your vault…</p>
    {:else if view==='connect'}<div class="grid gap-3"><form class="grid gap-3" onsubmit={e=>{e.preventDefault();void connect()}}><label class="grid gap-1 text-sm">Sync server<input class="rounded-lg border border-border bg-surface px-3 py-2" type="url" bind:value={endpoint} required/></label><button class="rounded-lg bg-primary px-4 py-2 text-on-primary" disabled={busy}>Connect</button></form>{#if hasLocalKey}<button class="text-sm text-danger" disabled={busy} onclick={()=>void forgetLocalAccess()}>Forget stored vault key and switch</button>{/if}{#if notice}<p class="text-sm text-primary">{notice}</p>{/if}</div>
    {:else if view==='setup'}<form class="grid gap-3" onsubmit={e=>{e.preventDefault();void claim()}}><p class="text-sm text-on-surface-muted">This is a new UnKeep server. Enter its one-time setup token. The server will not be initialized until you save a recovery kit.</p><label class="grid gap-1 text-sm">Setup token<input class="rounded-lg border border-border bg-surface px-3 py-2" type="password" autocomplete="off" bind:value={setupToken} required/></label><button class="rounded-lg bg-primary px-4 py-2 text-on-primary" disabled={busy}>Continue</button></form>
    {:else if view==='choose'}<div class="grid gap-3"><p class="text-sm text-on-surface-muted">Connect this device to your encrypted vault.</p><button class="rounded-lg bg-primary px-4 py-2 text-on-primary" onclick={()=>void startPairing()} disabled={busy}>Pair with another device</button><label class="cursor-pointer rounded-lg border border-border px-4 py-2 text-center focus-within:outline focus-within:outline-2 focus-within:outline-primary">Restore recovery kit<input class="sr-only" type="file" accept="application/json" onchange={e=>{const f=e.currentTarget.files?.[0];if(f)void restore(f)}}/></label>{#if hasLocalKey}<button class="text-sm text-danger" disabled={busy} onclick={()=>void forgetLocalAccess()}>Forget stored vault key and switch</button>{/if}</div>
    {:else if view==='pairing'}<div class="text-center"><p>On an unlocked device, approve this code:</p><p class="my-3 font-mono text-2xl tracking-widest">{pairing?.code}</p>{#if pairingQr}<img class="mx-auto h-40 w-40" src={pairingQr} alt="Pairing QR code"/>{/if}<p class="mt-3 text-sm text-on-surface-muted">Waiting for approval…</p><button class="mt-4 rounded-lg border border-border px-4 py-2" onclick={cancelPairing}>Cancel pairing</button></div>
    {:else if view==='recovery-confirm'}<div class="grid gap-3"><h2 class="font-semibold">Save your recovery kit</h2><p class="text-sm text-on-surface-muted">The server is still uninitialized. Save this kit before creating the vault so an interrupted setup cannot strand your data.</p><button class="rounded-lg border border-border px-4 py-2" onclick={()=>{downloadRecoveryKit(recoveryKit);recoverySaved=true}}>Download recovery kit</button><label class="flex gap-2 text-sm"><input type="checkbox" bind:checked={recoverySaved}/>I saved it somewhere safe</label><button class="rounded-lg bg-primary px-4 py-2 text-on-primary disabled:opacity-50" disabled={!recoverySaved||busy} onclick={()=>void finishSetup()}>Initialize and open UnKeep</button></div>
    {:else if view==='legacy-recovery-warning'}<div class="grid gap-3"><h2 class="font-semibold">Legacy recovery kit</h2><p class="text-sm text-on-surface-muted">This v1 kit does not identify a relay. Continue only if this is the relay that created the kit. The operator token proves permission to access the relay; it cannot prove that this legacy encryption key is correct.</p><button class="rounded-lg bg-primary px-4 py-2 text-on-primary disabled:opacity-50" disabled={busy} onclick={()=>void confirmLegacyRecovery()}>Associate kit with this relay</button><button class="rounded-lg border border-border px-4 py-2" disabled={busy} onclick={cancelLegacyRecovery}>Cancel</button></div>
    {:else if view==='reclaim'}<form class="grid gap-3" onsubmit={e=>{e.preventDefault();void reclaim()}}><h2 class="font-semibold">Recover vault access</h2><p class="text-sm text-on-surface-muted">Your recovery kit restored the encryption key locally. Enter the operator recovery token to mint a new device credential; the key is never sent to the server.</p><label class="grid gap-1 text-sm">Operator recovery token<input class="rounded-lg border border-border bg-surface px-3 py-2" type="password" autocomplete="off" bind:value={recoveryToken} required/></label><button class="rounded-lg bg-primary px-4 py-2 text-on-primary disabled:opacity-50" disabled={busy}>Recover access</button></form>{/if}
    {#if error}<p class="mt-4 text-sm text-danger" role="alert">{error}</p>{/if}
  </section></main>
{/if}
